INSERT INTO Language_ko_KR (Tag, Text)
VALUES	('TXT_KEY_BUILDING_NIGHTCLUB',			'나이트클럽'),
		('TXT_KEY_BUILDING_NIGHTCLUB_TEXT',		'나이트클럽에는 댄스 플로어, 레이저 조명 디스플레이, 라이브 음악이나 녹음된 음악을 믹싱하는 디스크자키(DJ)를 위한 무대가 있는 바와 디스코테크(일반적으로 디스코)가 있는 경우가 많습니다. 나이트클럽은 일반적으로 연령, 복장, 개인 소지품, 부적절한 행동 등의 측면에서 사람들의 출입을 제한합니다. 최초의 나이트클럽은 1840년대와 1850년대에 뉴욕시에 등장했는데, 맥글로리와 헤이마켓이 대표적입니다. 그들은 보드빌, 라이브 음악, 댄스 분야에서 전국적인 명성을 얻었습니다. 그들은 무허가 주류, 상업적 성매매, 그리고 주로 파로에서 행해지는 카드 도박을 묵인했습니다. 도시에서는 사실상 모든 도박이 불법이었고(고급 경마장은 제외), 정치 및 경찰 지도부에 대한 정기적인 뇌물 수수가 필수적이었습니다. 가격이 비쌌으며 상류층의 후원을 받았습니다.[NEWLINE][NEWLINE]나이트클럽은 1920년대에 민주화되었는데, 주크박스의 등장으로 금주법 시대에 지하 불법 스피크이지 바가 붐을 이루면서 생겨났습니다. 이 바에서는 음악은 필요했지만 라이브 밴드를 고용할 여력이 없었고, 유료 고객을 위한 귀중한 공간이 필요했습니다. 독일에서 디스크자키가 참여한 최초의 디스코는 1959년에 문을 연 스카치클럽이었습니다. (따라서 세계 최초의) DJ는 19세의 지역 기자 클라우스 키리니였는데, 그는 공개적으로 음반을 재생하는 이상한 새로운 현상에 대한 기사를 쓰기 위해 파견되었다. 위스키에 취한 그는 무대에 올라가 음반을 재생하면서 발표하기 시작했고, 무대 이름인 DJ 하인리히를 사용하기 시작했다. 그 이후로 음악과 춤의 조합은 시대에 따라 진화했으며, 오늘날 나이트클럽 장면은 예전과 마찬가지로 다양하고 인기가 많습니다.'),
		('TXT_KEY_BUILDING_NIGHTCLUB_STRATEGY',	'게임의 마지막 건물 중 하나인 나이트클럽은 도시의 관광 생산량을 엄청나게 늘릴 수 있게 해주지만, 도시가 지속적으로 성장할 수만 있다면 가능합니다. 여러분이 이용할 수 있는 모든 식량 증가 도구를 활용해 주요 관광지를 가장 트렌디한 장소로 만들어 보세요! 나이트클럽도 불행을 약간 줄여주지만, 거대한 도시를 키우면 문제가 생길 수 있으니 주의하세요...'),
		('TXT_KEY_BUILDING_NIGHTCLUB_HELP',		'');
--건설이 완료되면 [ICON_TOURISM] 관광 +750을 받습니다. 이 도시에서 [ICON_CITIZEN] 시민이 태어나면 즉시 해당 도시의 [ICON_TOURISM] 관광 생산량이 200% 증가합니다.[NEWLINE][NEWLINE]이 도시의 전문가 1명이 더 이상 [ICON_URBANIZATION] 도시화로 인한 [ICON_HAPPINESS_3] 불행을 생성하지 않습니다.